The structure of a basic RNN with one hidden layer is  illustrated in 
Figure~\ref{fig:rnn_architecture}, where the output $\mathbf{y}_t$ is determined 
by

\begin{equation}
P\left(\mathbf{y}_t \mid \{\mathbf{x}_d\}_{d=1}^t\right) = \mathrm{\phi} \left( 
\mathbf{W}_\mathrm{y} \mathbf{h}_t + \mathbf{b}_\mathrm{y} \right)
\label{eq:uni_y}
\end{equation}
where
\begin{equation}
\mathbf{h}_t = \tanh \left( \mathbf{W}_\mathrm{h} \mathbf{h}_{t-1} + \mathbf{W}_\mathrm{x} \mathbf{x}_{t} + \mathbf{b}_\mathrm{h} \right)
\label{eq:uni_h}
\end{equation}
and $\mathbf{W}_\mathrm{y}$, $\mathbf{W}_\mathrm{h}$, and 
$\mathbf{W}_\mathrm{x}$ are the weight matrices connecting the hidden to output 
layer, hidden to hidden layer, and input to hidden layer, respectively. 
$\mathbf{b}_\mathrm{y}$ and $\mathbf{b}_\mathrm{h}$ are the output and hidden 
layer bias vectors, respectively.

\begin{equation}
P\left(\mathbf{y}_t \mid \{\mathbf{x}_d\}_{d=1}^t\right) = \mathrm{\phi} \left( 
\mathbf{W}_\mathrm{y} \mathbf{h}_t + \mathbf{b}_\mathrm{y} \right)
\label{eq:uni_y}
\end{equation}

\begin{equation}
\mathbf{h}_t = \tanh \left( \mathbf{W}_\mathrm{h} \mathbf{h}_{t-1} + \mathbf{W}_\mathrm{x} \mathbf{x}_{t} + \mathbf{b}_\mathrm{h} \right)
\label{eq:uni_h}
\end{equation}

\begin{equation*}
P\left(\mathbf{y}_t \mid \{\mathbf{x}_d\}_{d\neq t}\right) = \mathrm{\phi} 
\left( \mathbf{W}_\mathrm{y}^\mathrm{f} 
\mathbf{h}_{t}^\mathrm{f} + \mathbf{W}_\mathrm{y}^\mathrm{b} 
\mathbf{h}_{t}^\mathrm{b} + \mathbf{b}_y \right), 
\end{equation*}

\begin{equation}
P\left(\mathbf{y}_t \mid \{\mathbf{x}_d\}_{d\neq t}\right) = \mathrm{\phi} 
\left( \mathbf{W}_\mathrm{y}^\mathrm{f} 
\mathbf{h}_{t-1}^\mathrm{f} + \mathbf{W}_\mathrm{y}^\mathrm{b} 
\mathbf{h}_{t+1}^\mathrm{b} + \mathbf{b}_y \right)
\label{eq:bi_y}
\end{equation}

\begin{align}
\mathbf{h}_t^\mathrm{f} &= \tanh \left( \mathbf{W}_\mathrm{h}^\mathrm{f} 
\mathbf{h}^\mathrm{f} _{t-1} + \mathbf{W}_\mathrm{x}^\mathrm{f} \mathbf{x}_{t} + 
\mathbf{b}_\mathrm{h}^\mathrm{f} \right)
\label{eq:bi_hf}
\\
\mathbf{h}_t^\mathrm{b} &= \tanh \left( \mathbf{W}_\mathrm{h}^\mathrm{b} 
\mathbf{h}^\mathrm{b}_{t+1} + \mathbf{W}_\mathrm{x}^\mathrm{b} \mathbf{x}_{t} 
+ \mathbf{b}_\mathrm{h}^\mathrm{b} \right).
\label{eq:bi_hb}
\end{align}

\begin{align}
P_{\mathrm{unidirectional}}(\mathbf{X}) = \prod_{t=1}^T P(\mathbf{x}_t \mid \{\mathbf{x}_d\}_{d=1}^{t-1}). 
\end{align}

\begin{align}
P_{\mathrm{NADE}}(\mathbf{X}\mid o_d) = \prod_{d=1}^T P(\mathbf{x}_{o_d} \mid \{\mathbf{x}_{o_{e}}\}_{e=1}^{d-1}).
\end{align}

As the unidirectional RNN 
models conditional probabilities of the form $P_{\mathrm{RNN}}(\mathbf{x}_t \mid 
\{\mathbf{x}_d\}_{d=1}^{t-1})$, we can use Bayes' theorem to derive:

\begin{align}
\hspace{2em}&\hspace{-2em} P_{\mathrm{RNN}}\left( \mathbf{x}_{t} = \mathbf{a} \mid \{\mathbf{x}_{d}\}_{d\neq t} \right) 
\\ 






& \propto P_{\mathrm{RNN}} \left( \mathbf{x}_t = \mathbf{a} \mid \{\mathbf{x}_d\}_{d=1}^{t-1} 
\right) P_{\mathrm{RNN}} \left(\{\mathbf{x}_e\}_{e=t+1}^{T} \mid \mathbf{x}_t = 
\mathbf{a}, \{\mathbf{x}_d\}_{d=1}^{t-1} \right) \\
&= \prod_{\tau=t}^T P_{\mathrm{RNN}}(\mathbf{x}_{\tau} \mid \{\mathbf{x}_d\}_{d=1}^{\tau-1}) \Bigr|_{\mathbf{x}_t=\mathbf{a}}
\label{eq:onewayrnn}
\end{align}
where $P_{\mathrm{RNN}}(\mathbf{x}_{\tau} \mid \{\mathbf{x}_d\}_{d=1}^{\tau-1})$ is directly 
the output of the unidirectional RNN given an input sequence $\mathbf{X}$, 
where one time step $t$, i.e. the one we Gibbs sample, is replaced by a proposal 
$\mathbf{a}$.

\begin{align}
\hspace{2em}&\hspace{-2em} P_{\mathrm{RNN}}\left( \mathbf{x}_{t} = \mathbf{a} \mid \{\mathbf{x}_{d}\}_{d\neq t} \right) 
\\ 






& \propto P_{\mathrm{RNN}} \left( \mathbf{x}_t = \mathbf{a} \mid \{\mathbf{x}_d\}_{d=1}^{t-1} 
\right) P_{\mathrm{RNN}} \left(\{\mathbf{x}_e\}_{e=t+1}^{T} \mid \mathbf{x}_t = 
\mathbf{a}, \{\mathbf{x}_d\}_{d=1}^{t-1} \right) \\
&= \prod_{\tau=t}^T P_{\mathrm{RNN}}(\mathbf{x}_{\tau} \mid \{\mathbf{x}_d\}_{d=1}^{\tau-1}) \Bigr|_{\mathbf{x}_t=\mathbf{a}}
\label{eq:onewayrnn}
\end{align}

\begin{equation*}
P_{\mathrm{one-gram}}\left(\mathbf{y}_t \right) = \mathrm{f} \left( \mathbf{b}_y \right).
\end{equation*}

